def transform(grid):
    if not grid:
        return grid

    counts = collections.Counter()
    for row in grid:
        for x in row:
            counts[x] += 1
    bg_color = max(counts, key=counts.get)

    height = len(grid)
    width = len(grid[0])

    result = [row[:] for row in grid]

    color_map = collections.defaultdict(list)
    for r in range(height):
        for c in range(width):
            if grid[r][c] != bg_color:
                color_map[grid[r][c]].append((r, c))

    # Process each color
    for color, pts in color_map.items():
        if len(pts) < 2:
            continue

        # Main diagonal (r - c = k)
        main_groups = collections.defaultdict(list)
        for r, c in pts:
            d = r - c
            main_groups[d].append((r, c))

        for pts_main in main_groups.values():
            if len(pts_main) < 2:
                continue
            pts_main.sort(key=lambda p: p[0])

            # Extend BOTH ways - this is the pattern that matches demos
            # UP-LEFT
            r, c = pts_main[0]
            while True:
                nr, nc = r - 1, c - 1
                if 0 <= nr < height and 0 <= nc < width and result[nr][nc] == bg_color:
                    result[nr][nc] = color
                    r, c = nr, nc
                else:
                    break

            # DOWN-RIGHT
            r, c = pts_main[-1]
            while True:
                nr, nc = r + 1, c + 1
                if 0 <= nr < height and 0 <= nc < width and result[nr][nc] == bg_color:
                    result[nr][nc] = color
                    r, c = nr, nc
                else:
                    break

        # Anti diagonal (r + c = k)
        anti_groups = collections.defaultdict(list)
        for r, c in pts:
            s = r + c
            anti_groups[s].append((r, c))

        for pts_anti in anti_groups.values():
            if len(pts_anti) < 2:
                continue
            pts_anti.sort(key=lambda p: p[0])

            # UP-RIGHT
            r, c = pts_anti[0]
            while True:
                nr, nc = r - 1, c + 1
                if 0 <= nr < height and 0 <= nc < width and result[nr][nc] == bg_color:
                    result[nr][nc] = color
                    r, c = nr, nc
                else:
                    break

            # DOWN-LEFT
            r, c = pts_anti[-1]
            while True:
                nr, nc = r + 1, c - 1
                if 0 <= nr < height and 0 <= nc < width and result[nr][nc] == bg_color:
                    result[nr][nc] = color
                    r, c = nr, nc
                else:
                    break

    return result

